#include <stdio.h>

#define MAXN 505

static char g[MAXN][MAXN];
static int qx[MAXN * MAXN];
static int qy[MAXN * MAXN];

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    for (int i = 0; i < N; i++) scanf("%s", g[i]);

    /* find the single leak on the first row */
    int start = -1;
    for (int j = 0; j < M; j++)
        if (g[0][j] == 'o') { start = j; break; }

    /* BFS closure applying exactly the three rules:
       from a wet cell (i,j):
         - if (i+1,j) == '.'  -> it gets wet (vertical drip)
         - if (i+1,j) == '#'  -> (i,j-1) and (i,j+1) get wet (spreading
                                 on top of the shelf, one cell past the
                                 edge, from where it drips again)        */
    int head = 0, tail = 0;
    if (start >= 0) { qx[tail] = 0; qy[tail] = start; tail++; }

    while (head < tail) {
        int i = qx[head], j = qy[head];
        head++;
        if (i + 1 < N) {
            if (g[i + 1][j] == '.') {
                g[i + 1][j] = 'o';
                qx[tail] = i + 1; qy[tail] = j; tail++;
            } else if (g[i + 1][j] == '#') {
                if (j + 1 < M && g[i][j + 1] == '.') {
                    g[i][j + 1] = 'o';
                    qx[tail] = i; qy[tail] = j + 1; tail++;
                }
                if (j - 1 >= 0 && g[i][j - 1] == '.') {
                    g[i][j - 1] = 'o';
                    qx[tail] = i; qy[tail] = j - 1; tail++;
                }
            }
        }
    }

    for (int i = 0; i < N; i++) {
        fputs(g[i], stdout);
        putchar('\n');
    }
    return 0;
}
